mapper.select:
SELECT P.DELIVERY_SERVICE_CODE
FROM ORDER_DETAIL OD
    JOIN PRODUCT P ON OD.PRODUCT_NO = P.PRODUCT_NO
WHERE OD.ORDER_NO = #{orderNo}
  AND P.SELLER_NO = #{sellerNo}
  AND ROWNUM = 1

SELECT COUNT(*)
FROM DELIVERY
WHERE DELIVERY_SERVICE_CODE = #{deliveryServiceCode}
  AND INVOICE_NO = #{invoiceNo}
